mapper.select:
SELECT s1.SEQ_NO as seqNo, s1.FILE_NAME as fileName,
s1.PATH as "path", s1.BUSINESS_ID as businessId,s1.SEQ_NO fileNo,to_char(s1.CREATE_TIME,'yyyy/MM/dd hh24:mi') createTimeText,
s2.real_name uploadUser
FROM SYS_UPLOAD_FILE_INFO s1
LEFT JOIN SYS_USER s2 ON s1.create_user = s2.user_name
WHERE BUSINESS_ID = #{businessId,jdbcType=VARCHAR}

    AND FILE_TYPE = #{fileType,jdbcType=VARCHAR}


    AND SEQNO_COMMENT IS NULL


    AND SEQNO_COMMENT = #{seqnoComment,jdbcType=VARCHAR}

ORDER BY s1.CREATE_TIME ASC
